using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;

// --- Configuration -----------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- DI & services -----------------------------------------------------------
var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddChatClient(b => b
    .UseLogging()
    .Use(new OpenAI.Chat.ChatClient(modelId, new ApiKeyCredential(apiKey))
        .AsIChatClient()));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();

// --- Tools -------------------------------------------------------------------
var notebook = new Notebook();

var searchTool = AIFunctionFactory.Create(
    (string query) =>
    {
        Console.WriteLine($"  🔍  Searching the web for: \"{query}\"");
        return WebSearch.SearchAsync(query);
    },
    "web_search",
    "Search the web for information on a topic. Returns a list of result snippets.");

var saveNoteTool = AIFunctionFactory.Create(
    ([Description("A concise label for the note")] string title,
     [Description("The note content to save")] string content) =>
    {
        notebook.Save(title, content);
        Console.WriteLine($"  📝  Note saved: \"{title}\"");
        return $"Note \"{title}\" saved successfully.";
    },
    "save_note",
    "Save a research note with a title and content for later summarization.");

var readNotesTool = AIFunctionFactory.Create(
    () =>
    {
        var notes = notebook.ReadAll();
        Console.WriteLine($"  📖  Reading {notes.Count} note(s)");
        return notes;
    },
    "read_notes",
    "Read all saved research notes.");

// --- Agent -------------------------------------------------------------------
var agent = new ChatClientAgent(chatClient,
    """
    You are a research agent. Your goal is to thoroughly research a topic the user
    gives you by searching the web, saving important findings as notes, then
    producing a well-organized summary.

    Workflow:
    1. Break the topic into 2-3 search queries that cover different angles.
    2. For each query, call web_search, review the results, and save the key
       findings using save_note.
    3. After all searches are done, call read_notes to review everything you
       collected.
    4. Write a concise, well-structured summary with sections and cite your sources.

    Always search before answering. Never fabricate information.
    """)
{
    Name = "ResearchAgent",
    Tools = [searchTool, saveNoteTool, readNotesTool],
};

// --- Run ---------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔬  Research Agent  🔬        ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or      ║");
Console.WriteLine("║  type 'quit' to exit.                ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.Write("Topic> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine();
    Console.WriteLine($"Researching: {topic}");
    Console.WriteLine(new string('─', 50));

    var history = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
    };

    var options = new AgentInvokeOptions { MaximumIterations = 10 };

    await foreach (var message in agent.InvokeStreamingAsync(history, options))
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
        {
            Console.Write(message.Text);
        }
    }

    Console.WriteLine();
    Console.WriteLine(new string('─', 50));
    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

// =============================================================================
// Supporting types
// =============================================================================

/// <summary>Simulated web search that returns canned results per query.</summary>
static class WebSearch
{
    public static Task<IReadOnlyList<SearchResult>> SearchAsync(string query)
    {
        // In production, replace with a real search API (Bing Search, Google Custom Search, etc.)
        var results = new List<SearchResult>
        {
            new($"https://example.com/article/{Uri.EscapeDataString(query.Replace(' ', '-'))}",
                $"Overview of {query}",
                $"A comprehensive introduction covering the key concepts, history, and current state of {query}. "
                + "This article explores the fundamentals and practical applications."),
            new($"https://research.example.org/{Uri.EscapeDataString(query.Replace(' ', '-'))}",
                $"Recent developments in {query}",
                $"Latest research and developments in the field of {query}, including breakthroughs from 2025-2026 "
                + "and future directions identified by leading experts."),
            new($"https://news.example.com/{Uri.EscapeDataString(query.Replace(' ', '-'))}",
                $"{query} — practical applications",
                $"Real-world applications and case studies showing how {query} is being used in industry today, "
                + "with data on adoption rates and measurable outcomes."),
        };

        return Task.FromResult<IReadOnlyList<SearchResult>>(results);
    }
}

record SearchResult(string Url, string Title, string Snippet);

/// <summary>Simple in-memory notebook for the agent to store research findings.</summary>
class Notebook
{
    private readonly List<Note> _notes = [];

    public void Save(string title, string content) =>
        _notes.Add(new Note(title, content, DateTime.UtcNow));

    public IReadOnlyList<Note> ReadAll() => _notes.AsReadOnly();
}

record Note(string Title, string Content, DateTime SavedAt);

