using Microsoft.Extensions.Logging;
using OpenAI;

// --- Configuration -----------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- DI & services -----------------------------------------------------------
var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddChatClient(b => b
    .UseLogging()
    .Use(new OpenAI.Chat.ChatClient(modelId, new ApiKeyCredential(apiKey))
        .AsIChatClient()));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();
var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

// --- Tools -------------------------------------------------------------------
var notebook = new Notebook();

var searchTool = AIFunctionFactory.Create(
    (string query) =>
    {
        Console.WriteLine($"  🔍  Searching the web for: \"{query}\"");
        return WebSearch.SearchAsync(query);
    },
    "web_search",
    "Search the web for information on a topic. Returns a list of result snippets.");

var saveNoteTool = AIFunctionFactory.Create(
    ([Description("A concise label for the note")] string title,
     [Description("The note content to save")] string content) =>
    {
        notebook.Save(title, content);
        Console.WriteLine($"  📝  Note saved: \"{title}\"");
        return $"Note \"{title}\" saved successfully.";
    },
    "save_note",
    "Save a research note with a title and content for later summarization.");

var readNotesTool = AIFunctionFactory.Create(
    () =>
    {
        var notes = notebook.ReadAll();
        Console.WriteLine($"  📖  Reading {notes.Count} note(s)");
        return notes;
    },
    "read_notes",
    "Read all saved research notes.");

// --- Agent -------------------------------------------------------------------
var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [searchTool, saveNoteTool, readNotesTool],
};

var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An agent that researches topics using web search and note-taking.",
        ChatOptions = chatOptions,
    },
    loggerFactory);

agent.Instructions =
    """
    You are a research agent. Your goal is to thoroughly research a topic the user
    gives you by searching the web, saving important findings as notes, then
    producing a well-organized summary.

    Workflow:
    1. Break the topic into 2-3 search queries that cover different angles.
    2. For each query, call web_search, review the results, and save the key
       findings using save_note.
    3. After all searches are done, call read_notes to review everything you
       collected.
    4. Write a concise, well-structured summary with sections and cite your sources.

    Always search before answering. Never fabricate information.
    """;

// --- Run ---------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔬  Research Agent  🔬        ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or      ║");
Console.WriteLine("║  type 'quit' to exit.                ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.Write("Topic> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine();
    Console.WriteLine($"Researching: {topic}");
    Console.WriteLine(new string('─', 50));

    notebook.Clear();

    var session = await agent.CreateSessionAsync(
        conversationId: Guid.NewGuid().ToString());

    await foreach (var update in agent.RunStreamingAsync(
        $"Research the following topic and provide a summary: {topic}", session))
    {
        if (update.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(update.Text))
        {
            Console.Write(update.Text);
        }
    }

    Console.WriteLine();
    Console.WriteLine(new string('─', 50));
    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

// --- Cleanup -----------------------------------------------------------------
rm -rf /tmp/inspect 2>/dev/null

