        var results = new List<SearchResult>
        {
            new($"https://example.com/article/{Uri.EscapeDataString(query.Replace(' ', '-'))}",
                $"Overview of {query}",
                $"A comprehensive introduction covering the key concepts, history, and current state of {query}. "
                + "This article explores the fundamentals and practical applications."),
            new($"https://research.example.org/{Uri.EscapeDataString(query.Replace(' ', '-'))}",
                $"Recent developments in {query}",
                $"Latest research and developments in the field of {query}, including breakthroughs from 2025-2026 "
                + "and future directions identified by leading experts."),
            new($"https://news.example.com/{Uri.EscapeDataString(query.Replace(' ', '-'))}",
                $"{query} — practical applications",
                $"Real-world applications and case studies showing how {query} is being used in industry today, "
